package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsBakeService {
 @GameTest(template="empty") public static void fullRawPantryCanBakeWhenCheaperRetailCannotFit(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);var b=baker(f);var family=client(f,b);var stores=f.r.stocks(family.id);RuralRules.put(stores,false,30);b.listed[1].add(64,0);b.outputCredit=4;b.breadRemaining=4;long cash=f.t.money(f.s),grain=f.t.grain(f.s),fees=b.bakeFees;h.assertTrue(f.t.quote(f.s,family.city,1,0)<=f.t.quote(f.s,family.city,0,0)+CityBakeService.fee(f.t)&&RuralRules.capacity(stores)==0,"Retail is cheaper but cannot fit into raw-full pantry");int n=CityBakeService.serve(f.s,b);h.assertTrue(n==4&&RuralRules.count(stores,false)==26&&RuralRules.count(stores,true)==4,"Existing paid service converts own grain in place despite cheaper unreachable retail");h.assertTrue(b.bakeFees==fees+8&&b.outputCredit==0&&b.breadRemaining==0&&b.listed[1].count==64&&f.t.money(f.s)==cash&&f.t.grain(f.s)==grain,"Still pays fee2, spends actual shared work, leaves retail stock untouched and conserves money/grain");}h.succeed();}
 @GameTest(template="empty") public static void serviceDoesNotDisplaceAlreadyCoveredHouseholdCooking(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);var b=baker(f);var family=client(f,b);var stores=f.r.stocks(family.id);RuralRules.put(stores,false,20);RuralRules.put(stores,true,RuralRules.demand(family,f.r.state.people));h.assertTrue(CityBakeService.wanted(f.s,family)==0,"Already covered next meal does not order three-day reserves and idle the home cook");RuralRules.take(stores,true,20);var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();home.credit=2;f.t.state.households.put(family.id,home);h.assertTrue(CityBakeService.wanted(f.s,family)==Math.max(0,RuralRules.demand(family,f.r.state.people)-2),"Already earned home work is reserved before ordering");}h.succeed();}
 @GameTest(template="empty") public static void retailForecastCannotDuplicateAffordableProcessingDemand(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);for(var family:f.r.state.families.values())if(family.city.equals(f.city.id)){RuralRules.put(f.r.stocks(family.id),false,30);var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();f.t.state.households.put(family.id,home);}h.assertTrue(CityBakeService.retailDemand(f.s,f.city.id)<=CityRelief.forecast(f.s,f.city.id),"Private raw food already covered by home/service is not counted again as retail orders");var family=client(f,baker(f));RuralRules.take(f.r.stocks(family.id),false,30);f.e.state.accounts.put(CityEconomy.person(family.members.getFirst()),100L);h.assertTrue(CityBakeService.retailDemand(f.s,f.city.id)>0,"An affordable real shortage still creates retail demand");}h.succeed();}
 static CityTrade.Business baker(CityTestsScale.Fixture f){return f.t.state.businesses.values().stream().filter(b->b.kind.equals("baker")).findFirst().orElseThrow();}
 static RuralRules.Family client(CityTestsScale.Fixture f,CityTrade.Business b){return f.r.state.families.values().stream().filter(v->v.city.equals(b.city)&&!v.members.contains(b.owner)).findFirst().orElseThrow();}
 static void clear(CityTestsScale.Fixture f){for(var v:f.r.state.boxes.values()){v.stock.wheat=v.stock.bread=0;RuralMeat.clear(v.stock);}}
 @GameTest(template="empty") public static void paidBakingTransformsRealGrainInFullPantry(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);var b=baker(f);var home=client(f,b);var stores=f.r.stocks(home.id);RuralRules.put(stores,false,30);b.outputCredit=4;b.breadRemaining=4;long money=f.t.money(f.s),grain=f.t.grain(f.s),fees=b.bakeFees;int n=CityBakeService.serve(f.s,b);h.assertTrue(n==4&&RuralRules.count(stores,false)==26&&RuralRules.count(stores,true)==4&&RuralRules.capacity(stores)==0,"Full pantry exchanges four real wheat into four bread without extra storage");h.assertTrue(b.bakeFees==fees+4*CityBakeService.fee(f.t)&&b.bakeUnits==4&&b.outputCredit==0&&b.breadRemaining==0,"Exactly four fees and shared work quota consumed");h.assertTrue(f.t.money(f.s)==money&&f.t.grain(f.s)==grain&&CityBakeService.serve(f.s,b)==0,"No minted food/currency or replayed work");h.assertTrue(stores.stream().filter(v->v.bread>0).allMatch(v->v.ages[1].groups.stream().allMatch(g->g.age==0)),"Processed bread starts fresh");}h.succeed();}
 @GameTest(template="empty") public static void missingInputsPaymentOrWorkNeverCreatesAnOrder(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);var b=baker(f);b.outputCredit=20;b.breadRemaining=20;long total=f.t.money(f.s);h.assertTrue(CityBakeService.serve(f.s,b)==0,"No household wheat means no order");var family=client(f,b);RuralRules.put(f.r.stocks(family.id),false,8);for(var id:family.members)f.e.state.accounts.put(CityEconomy.person(id),0L);total=f.t.money(f.s);h.assertTrue(CityBakeService.serve(f.s,b)==0&&RuralRules.count(f.r.stocks(family.id),false)==8&&f.t.money(f.s)==total,"No fee money leaves wheat untouched");f.e.state.accounts.put(CityEconomy.person(family.members.getFirst()),10L);b.outputCredit=0;h.assertTrue(CityBakeService.serve(f.s,b)==0,"No earned baking work");b.outputCredit=20;b.closing=true;h.assertTrue(CityBakeService.serve(f.s,b)==0,"Closed bakery cannot fulfill orders");}h.succeed();}
 @GameTest(template="empty") public static void workCannotBeEarnedTwiceWithinSegment(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=baker(f);b.outputCredit=0;b.bakeSegment=-1;CityBakeService.earn(f.s,b,0);double credit=b.outputCredit;CityBakeService.earn(f.s,b,0);h.assertTrue(credit>0&&credit<=20&&b.outputCredit==credit,"One work segment supplies one shared credit budget");b.outputCredit=0;CityBakeService.earn(f.s,b,0);h.assertTrue(b.outputCredit==0,"Spending credit cannot earn it again at same time");}h.succeed();}
 @GameTest(template="empty") public static void sharedPlanLeavesOnlyResidualDemand(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var home=new FamilyLivelihood.Home();h.assertTrue(HouseholdCooking.cityDaily(home)==3.5&&HouseholdCooking.ruralRate(new RuralRules.Person())==30,"City primary3/day; unrelated fallback rate preserved");var cook=new RuralRules.Person();cook.role=RuralRules.Role.COOK;h.assertTrue(HouseholdCooking.ruralRate(cook)/3==4.5,"Rural cook4.5/day, not a five-fold gap");home.secondary=true;h.assertTrue(HouseholdCooking.cityDaily(home)==1.75,"Secondary home work retains half rate");var b=baker(f);CityBaking.plan(f.s,b.city);int planned=b.breadRemaining;CityBaking.plan(f.s,b.city);h.assertTrue(planned>=0&&planned<=80&&b.breadRemaining==planned,"Plan evaluated only once/day and common cap80 remains");}h.succeed();}
 @GameTest(template="empty") public static void householdMeatRetainsOriginalWorkRate(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);clear(f);var b=baker(f);var family=client(f,b);var home=new FamilyLivelihood.Home();home.processor=family.members.getFirst();home.credit=HouseholdCooking.URBAN_RATE;f.t.state.households.put(family.id,home);var stores=f.r.stocks(family.id);RuralMeat.put(stores,false,0,12);FamilyLivelihood.cook(f.s,family);int n=RuralMeat.count(stores,true,0);h.assertTrue(n>3&&Math.abs(home.credit-(HouseholdCooking.URBAN_RATE-n*HouseholdCooking.URBAN_RATE/30))<1e-8,"Only bread productivity changes; actual meat uses original shared time cost");}h.succeed();}
}
